  /// Search all provinces and districts
  static List<CityLocation> search(String query) {
    final q = query.trim().toLowerCase();
    if (q.isEmpty) return [];
    final List<CityLocation> results = [];
    for (final h in holyCities) {
      if (h.name.toLowerCase().contains(q)) results.add(h);
    }
    for (final p in provinces) {
      if (p.name.toLowerCase().contains(q)) {
        results.add(CityLocation(name: p.name, latitude: p.latitude, longitude: p.longitude, qiblaAngle: p.qiblaAngle));
      }
      for (final d in p.districts) {
        if (d.name.toLowerCase().contains(q) && !results.any((r) => r.name == d.name)) {
          results.add(d);
        }
      }
    }
    return results;
  }
